import { v4 as uuidv43 } from "uuid";
import { eq as eq9 } from "drizzle-orm";
function extractAuditUser(userUuid, data) {
  if (userUuid) return userUuid;
  if (data && "auditUserUuid" in data) {
    const val = data.auditUserUuid;
    delete data.auditUserUuid;
    return val;
  }
  return null;
}
async function resolveUserUuid(value) {
  if (!value) return null;
  const db = getDb();
  const byUuid = await db.select().from(masterUsers).where(eq9(masterUsers.userUuid, value)).limit(1);
  if (byUuid.length > 0 && byUuid[0].userUuid) {
    return byUuid[0].userUuid;
  }
  const displayNameParts = value.split(" ,");
  if (displayNameParts.length === 2) {
    const fullname = displayNameParts[0].trim();
    const designation = displayNameParts[1].trim();
    const results = await db.select().from(masterUsers).where(eq9(masterUsers.fullname, fullname)).limit(10);
    const exactMatch = results.find((u) => u.designation === designation);
    if (exactMatch && exactMatch.userUuid) {
      return exactMatch.userUuid;
    }
    if (results.length > 0 && results[0].userUuid) {
      return results[0].userUuid;
    }
  }
  const byFullname = await db.select().from(masterUsers).where(eq9(masterUsers.fullname, value)).limit(1);
  if (byFullname.length > 0 && byFullname[0].userUuid) {
    return byFullname[0].userUuid;
  }
  return null;
}
