init_db();
init_schema();
import { eq as eq10 } from "drizzle-orm";
async function resolveVesselTypeUuid(value) {
  if (!value) return null;
  const db = getDb();
  const byUuid = await db.select().from(masterVesselTypes).where(eq10(masterVesselTypes.vtUuid, value)).limit(1);
  if (byUuid.length > 0 && byUuid[0].vtUuid) {
    return byUuid[0].vtUuid;
  }
  const byName = await db.select().from(masterVesselTypes).where(eq10(masterVesselTypes.vesselType, value)).limit(1);
  if (byName.length > 0 && byName[0].vtUuid) {
    return byName[0].vtUuid;
  }
  return null;
}
async function resolveFleetGroupUuid(value) {
  if (!value) return null;
  const db = getDb();
  const byUuid = await db.select().from(masterFleetGroups).where(eq10(masterFleetGroups.fgUuid, value)).limit(1);
  if (byUuid.length > 0 && byUuid[0].fgUuid) {
    return byUuid[0].fgUuid;
  }
  const byName = await db.select().from(masterFleetGroups).where(eq10(masterFleetGroups.name, value)).limit(1);
  if (byName.length > 0 && byName[0].fgUuid) {
    return byName[0].fgUuid;
  }
  return null;
}
