router.get("/fleet-groups", async (_req, res) => {
  try {
    const { getDb: getDb2 } = await Promise.resolve().then(() => (init_db(), db_exports));
    const { masterFleetGroups: masterFleetGroups2 } = await Promise.resolve().then(() => (init_schema(), schema_exports));
    const db = getDb2();
    const fleetGroups = await db.select({
      fgUuid: masterFleetGroups2.fgUuid,
      name: masterFleetGroups2.name,
      vessels: masterFleetGroups2.vessels
    }).from(masterFleetGroups2);
    res.json({ fleetGroups });
  } catch (error) {
    console.error("Error fetching fleet groups:", error);
    res.status(500).json({ error: "Failed to fetch fleet groups" });
  }
});
