async function resolvePortToUuid(portValue) {
  if (!portValue) return null;
  const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (uuidPattern.test(portValue)) {
    return portValue;
  }
  const db = getDb();
  const byName = await db.select({ portUuid: masterPorts.portUuid }).from(masterPorts).where(sql8`UPPER(${masterPorts.name}) = UPPER(${portValue.trim()})`).limit(1);
  if (byName.length > 0) {
    return byName[0].portUuid;
  }
  console.warn(`Could not resolve port value to UUID: ${portValue}`);
  return null;
}
