async function calculateExpiryCountsForCrew(crewUuid) {
  if (!crewUuid) {
    return { docExpiringCount: "0/0", medicalExpiring: "-" };
  }
  const db = getDb();
  const today = /* @__PURE__ */ new Date();
  today.setHours(0, 0, 0, 0);
  const twoMonthsFromNow = new Date(today);
  twoMonthsFromNow.setMonth(twoMonthsFromNow.getMonth() + 2);
  let expiredDocs = 0;
  let expiringDocs = 0;
  let medicalExpiring = "-";
  try {
    const analyzeExpiry = (expiry) => {
      if (!expiry) return;
      const expiryDate = new Date(expiry);
      if (isNaN(expiryDate.getTime())) return;
      expiryDate.setHours(0, 0, 0, 0);
      if (expiryDate < today) {
        expiredDocs++;
      } else if (expiryDate <= twoMonthsFromNow) {
        expiringDocs++;
      }
    };
    const docs = await db.select().from(crewDocuments).where(and29(
      eq34(crewDocuments.crewUuid, crewUuid),
      eq34(crewDocuments.isDeleted, false)
    ));
    for (const doc of docs) {
      analyzeExpiry(doc.expiry);
    }
    const visas = await db.select().from(crewVisas).where(and29(
      eq34(crewVisas.crewUuid, crewUuid),
      eq34(crewVisas.isDeleted, false)
    ));
    for (const visa of visas) {
      analyzeExpiry(visa.expiry);
    }
    const licenses = await db.select().from(crewLicenses).where(and29(
      eq34(crewLicenses.crewUuid, crewUuid),
      eq34(crewLicenses.isDeleted, false)
    ));
    for (const lic of licenses) {
      analyzeExpiry(lic.expiry);
    }
    const training = await db.select().from(crewTrainingCourses).where(and29(
      eq34(crewTrainingCourses.crewUuid, crewUuid),
      eq34(crewTrainingCourses.isDeleted, false)
    ));
    for (const t of training) {
      analyzeExpiry(t.expiry);
    }
    const medicals = await db.select().from(crewPreJoiningMedicals).where(and29(
      eq34(crewPreJoiningMedicals.crewUuid, crewUuid),
      eq34(crewPreJoiningMedicals.isDeleted, false)
    ));
    if (medicals.length > 0) {
      const sortedMedicals = [...medicals].sort((a, b) => {
        const dateA = a.examinationDate ? new Date(a.examinationDate).getTime() : 0;
        const dateB = b.examinationDate ? new Date(b.examinationDate).getTime() : 0;
        return dateB - dateA;
      });
      const latestMedical = sortedMedicals[0];
      if (latestMedical.expiryDate) {
        const medExpiry = new Date(latestMedical.expiryDate);
        medExpiry.setHours(0, 0, 0, 0);
        const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
        const day = String(medExpiry.getDate()).padStart(2, "0");
        const month = months[medExpiry.getMonth()];
        const year = medExpiry.getFullYear();
        medicalExpiring = `${day}-${month}-${year}`;
      }
    }
  } catch (error) {
    console.error(`Error calculating expiry counts for crew ${crewUuid}:`, error);
  }
  return {
    docExpiringCount: `${expiringDocs}/${expiredDocs}`,
    medicalExpiring
  };
}
