// server/v2/rest-hours/utils/reviewStatusUtils.ts
function calculateVesselReviewStatus(monthValue, vesselReviewSubmittedDate) {
  if (vesselReviewSubmittedDate) {
    return "Completed";
  }
  if (!monthValue || !monthValue.includes("-")) {
    return "";
  }
  const [year, month] = monthValue.split("-").map(Number);
  const nextMonth = new Date(year, month, 1);
  const overdueDate = new Date(year, month, 7);
  const now = /* @__PURE__ */ new Date();
  now.setHours(0, 0, 0, 0);
  if (now < nextMonth) {
    return "";
  }
  if (now >= overdueDate) {
    return "Overdue";
  }
  return "Due";
}
function calculateOfficeReviewStatus(monthValue, vesselReviewSubmittedDate, officeReviewSubmittedDate) {
  if (officeReviewSubmittedDate) {
    return "Completed";
  }
  if (!vesselReviewSubmittedDate) {
    return "";
  }
  if (!monthValue || !monthValue.includes("-")) {
    return "";
  }
  const [year, month] = monthValue.split("-").map(Number);
  const nextMonth = new Date(year, month, 1);
  const overdueDate = new Date(year, month, 10);
  const now = /* @__PURE__ */ new Date();
  now.setHours(0, 0, 0, 0);
  if (now < nextMonth) {
    return "";
  }
  if (now >= overdueDate) {
    return "Overdue";
  }
  return "Due";
}
function enrichRecordWithReviewStatuses(record) {
  const monthValue = record.monthValue || "";
  return {
    ...record,
    vesselReviewStatus: calculateVesselReviewStatus(
      monthValue,
      record.vesselReviewSubmittedDate
    ),
    officeReviewStatus: calculateOfficeReviewStatus(
      monthValue,
      record.vesselReviewSubmittedDate,
      record.officeReviewSubmittedDate
    )
  };
}

