// server/v2/rest-hours/controllers/masterDataController.ts
init_db();
init_schema();
import { eq as eq57, isNull as isNull13, or as or11, and as and51, sql as sql14, count } from "drizzle-orm";
var masterDataController = {
  async getVessels(req, res) {
    try {
      const db = getDb();
      const vessels2 = await db.select({
        id: masterVessels.id,
        vesselUuid: masterVessels.vesselUuid,
        vessel: masterVessels.vessel,
        imoNumber: masterVessels.imoNumber,
        vesselType: masterVessels.vesselType
      }).from(masterVessels).orderBy(sql14`LOWER(${masterVessels.vessel})`);
      res.json(vessels2);
    } catch (error) {
      console.error("Error fetching master vessels:", error);
      res.status(500).json({ error: "Failed to fetch vessels" });
    }
  },
  async getCrewMembers(req, res) {
    try {
      const db = getDb();
      const query = db.select({
        id: crewMembersV2.id,
        crewUuid: crewMembersV2.crewUuid,
        empNo: crewMembersV2.empNo,
        firstName: crewMembersV2.firstName,
        middleName: crewMembersV2.middleName,
        familyName: crewMembersV2.familyName,
        presentRank: crewMembersV2.presentRank,
        vesselUuid: crewAssignments.vesselUuid,
        status: crewMembersV2.status,
        isActive: crewMembersV2.isActive,
        uploadedPhoto: crewMembersV2.uploadedPhoto
      }).from(crewMembersV2).leftJoin(
        crewAssignments,
        and51(
          eq57(crewMembersV2.crewUuid, crewAssignments.crewUuid),
          eq57(crewAssignments.isCurrent, true)
        )
      ).where(
        or11(
          eq57(crewMembersV2.isDeleted, false),
          isNull13(crewMembersV2.isDeleted)
        )
      );
      const crewMembers2 = await query;
      const formattedCrew = crewMembers2.map((crew) => ({
        ...crew,
        name: [crew.firstName, crew.middleName, crew.familyName].filter(Boolean).join(" "),
        rank: crew.presentRank,
        crewMemberId: crew.empNo,
        presentVessel: crew.vesselUuid
      }));
      res.json(formattedCrew);
    } catch (error) {
      console.error("Error fetching crew members V2:", error);
      res.status(500).json({ error: "Failed to fetch crew members" });
    }
  },
  async getCrewCountByVessel(req, res) {
    try {
      const db = getDb();
      const crewCounts = await db.select({
        vesselUuid: crewAssignments.vesselUuid,
        crewCount: count(crewAssignments.id)
      }).from(crewAssignments).innerJoin(
        crewMembersV2,
        eq57(crewAssignments.crewUuid, crewMembersV2.crewUuid)
      ).where(
        and51(
          eq57(crewAssignments.isCurrent, true),
          or11(
            eq57(crewMembersV2.isDeleted, false),
            isNull13(crewMembersV2.isDeleted)
          )
        )
      ).groupBy(crewAssignments.vesselUuid);
      const countMap = {};
      for (const row of crewCounts) {
        if (row.vesselUuid) {
          countMap[row.vesselUuid] = Number(row.crewCount);
        }
      }
      res.json(countMap);
    } catch (error) {
      console.error("Error fetching crew count by vessel:", error);
      res.status(500).json({ error: "Failed to fetch crew count" });
    }
  }
};

