var rankGroupsRepo2 = new RankGroupsRepository();
var formsRepo2 = new FormsRepository();
var formVersionsRepo2 = new FormVersionsRepository();
async function syncFormRankGroup(formId) {
  const activeGroups = await rankGroupsRepo2.findByFormId(formId, false);
  const rankGroupNames = activeGroups.map((rg) => rg.name).join(", ");
  await formsRepo2.updateById(formId, { rankGroup: rankGroupNames || "" });
}
async function createFormVersionOnConfigSave(formId, rankGroupId, configuration) {
  try {
    const form = await formsRepo2.findById(formId);
    if (!form) return;
    const existingVersions = await formVersionsRepo2.findByFormId(formId);
    const rgVersions = existingVersions.filter((v) => v.rankGroupId === rankGroupId);
    const maxVersionNo = rgVersions.reduce((max, v) => {
      const vNo = parseInt(v.versionNo, 10);
      return isNaN(vNo) ? max : Math.max(max, vNo);
    }, 0);
    const nextVersionNo = String(maxVersionNo + 1).padStart(2, "0");
    const now = /* @__PURE__ */ new Date();
    const versionDate = now.toLocaleDateString("en-GB", {
      day: "2-digit",
      month: "short",
      year: "numeric"
    }).replace(/ /g, "-");
    await formVersionsRepo2.create({
      formId,
      rankGroupId,
      versionNo: nextVersionNo,
      versionDate,
      status: "released",
      configuration,
      releasedAt: now
    });
    const globalMax = existingVersions.reduce((max, v) => {
      const vNo = parseInt(v.versionNo, 10);
      return isNaN(vNo) ? max : Math.max(max, vNo);
    }, 0);
    const globalNextVersion = String(Math.max(globalMax + 1, parseInt(nextVersionNo, 10))).padStart(2, "0");
    await formsRepo2.updateById(formId, {
      versionNo: globalNextVersion,
      versionDate
    });
    console.log(`\u2705 [V2 VERSION] Created version ${nextVersionNo} for form ${formId}, rankGroup ${rankGroupId} (global form version: ${globalNextVersion})`);
  } catch (error) {
    console.error(`\u26A0\uFE0F [V2 VERSION] Failed to create version for form ${formId}:`, error);
  }
}
function checkRankConflicts(activeGroups, newRanks, excludeId) {
  const conflicts = {};
  for (const group of activeGroups) {
    if (excludeId && group.id === excludeId) continue;
    let groupRanks = [];
    try {
      groupRanks = typeof group.ranks === "string" ? JSON.parse(group.ranks) : group.ranks;
    } catch (e) {
      groupRanks = [];
    }
    for (const rank of newRanks) {
      if (groupRanks.includes(rank)) {
        conflicts[rank] = group.name;
      }
    }
  }
  return conflicts;
}
