var companyTrainingsRepo2 = new CompanyTrainingsRepository();
var trainingMasterRepo2 = new TrainingMasterRepository();
var companyTrainingsService = {
  async getAll() {
    return companyTrainingsRepo2.findAll();
  },
  async getById(id) {
    const record = await companyTrainingsRepo2.findById(id);
    if (!record) throw new Error(`Company training not found: ${id}`);
    return record;
  },
  async create(data) {
    return companyTrainingsRepo2.create(applyAuditUser21(data, true));
  },
  async updateById(id, data) {
    const updated = await companyTrainingsRepo2.updateById(id, applyAuditUser21(data));
    if (!updated) throw new Error(`Company training not found: ${id}`);
    return updated;
  },
  async deleteById(id) {
    const existing = await companyTrainingsRepo2.findById(id);
    if (!existing) throw new Error(`Company training not found: ${id}`);
    return companyTrainingsRepo2.softDeleteById(id);
  },
  async importFromMaster() {
    const masters = await trainingMasterRepo2.findAll();
    const applicableMasters = masters.filter((m) => m.applicableToCompany);
    const results = [];
    for (const master of applicableMasters) {
      const existing = await companyTrainingsRepo2.findByMasterId(master.id);
      if (existing.length === 0) {
        const created = await companyTrainingsRepo2.createFromMaster(
          master.id,
          master.trainingLabel || master.trainingName,
          "default"
        );
        results.push(created);
      }
    }
    return results;
  },
  async reorder(orders) {
    return companyTrainingsRepo2.reorder(orders);
  }
};

