// server/v2/admin/services/trainingMatrixVesselRevisionsService.ts
var tmVesselRevisionsRepo = new TrainingMatrixVesselRevisionsRepository();
var tmVesselDraftsRepo2 = new TrainingMatrixVesselDraftsRepository();
var trainingMatrixVesselRevisionsService = {
  async getAll() {
    return tmVesselRevisionsRepo.findAll();
  },
  async getById(id) {
    const record = await tmVesselRevisionsRepo.findById(id);
    if (!record) throw new Error(`Training matrix vessel revision not found: ${id}`);
    return record;
  },
  async getByVesselId(vesselId) {
    return tmVesselRevisionsRepo.findByVesselId(vesselId);
  },
  async create(data) {
    return tmVesselRevisionsRepo.create(applyAuditUser21(data, true));
  },
  async getNextRevision(vesselId) {
    return tmVesselRevisionsRepo.getNextRevision(vesselId);
  },
  async submit(data) {
    const autoAssignedRevision = await tmVesselRevisionsRepo.getNextRevision(data.vesselId);
    const revision = await tmVesselRevisionsRepo.create(applyAuditUser21({
      vesselId: data.vesselId,
      revision: autoAssignedRevision,
      revisionDate: data.revisionDate,
      revisionData: data.revisionData,
      auditUserUuid: data.auditUserUuid
    }, true));
    const existingDrafts = await tmVesselDraftsRepo2.findByVesselId(data.vesselId);
    let deletedDrafts = 0;
    for (const draft of existingDrafts) {
      const deleted = await tmVesselDraftsRepo2.hardDeleteById(draft.id);
      if (deleted) deletedDrafts++;
    }
    return {
      success: true,
      revision,
      metadata: { autoAssignedRevision, deletedDrafts }
    };
  }
};

