var mastersRepo = new MastersRepository();
function addVesselAliases(row) {
  return { ...row, uuid: row.vesselUuid, name: row.vessel };
}
function addVesselTypeAliases(row) {
  return { ...row, uuid: row.vtUuid, name: row.vesselType };
}
function addNationalityAliases(row) {
  return { ...row, uuid: row.natUuid, name: row.nationality };
}
function addCountryAliases(row) {
  return { ...row, uuid: row.countryUuid, name: row.countryName };
}
function addPortAliases(row) {
  return { ...row, uuid: row.portUuid };
}
function addLanguageAliases(row) {
  return { ...row, uuid: row.langUuid, name: row.languageName };
}
function addFleetGroupAliases(row) {
  return { ...row, uuid: row.fgUuid };
}
function addAdditionalGroupAliases(row) {
  return { ...row, uuid: row.agUuid };
}
function addUserAliases(row) {
  return { ...row, uuid: row.userUuid, userName: row.displayName };
}
function addLicenseDceAliases(row) {
  return { ...row, uuid: row.id };
}
function addManningAgentAliases(row) {
  return { ...row, uuid: row.id };
}
function addCrewPoolAliases(row) {
  return { ...row, uuid: row.id };
}
function addAppraisalTypeAliases(row) {
  return { ...row, uuid: row.id };
}
